import sys
from decimal import Decimal
def main():
    d = {}
    data = sys.stdin.buffer.read().split(b'\n')
    for line in data[1:]:
        if not line:
            continue
        p = line.strip().split(b',')
        c = p[1]
        d[c] = d.get(c, 0) + Decimal(p[2].decode())
    out = []
    for c in sorted(d):
        out.append("%s,%.2f" % (c.decode(), d[c]))
    sys.stdout.write("\n".join(out) + ("\n" if out else ""))
main()
